function applyPreview(){var img=el('previewImage'),overlay=el('previewState'),revision=state.previewRevision;if(!img||!overlay)return;if(!revision){overlay.textContent='Waiting for the first committed presentation';overlay.classList.remove('hidden');img.removeAttribute('src');delete img.dataset.previewRevision;return}if(img.dataset.previewRevision===revision||img.dataset.loadingRevision===revision)return;img.dataset.loadingRevision=revision;overlay.textContent='Loading preview…';overlay.classList.remove('hidden');rawFetch('/api/v1/preview?revision='+encodeURIComponent(revision)).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.blob()}).then(function(blob){if(state.previewRevision!==revision){return}if(img.dataset.objectUrl)URL.revokeObjectURL(img.dataset.objectUrl);var url=URL.createObjectURL(blob);img.dataset.objectUrl=url;img.dataset.previewRevision=revision;img.onload=function(){if(img.dataset.previewRevision===revision)overlay.classList.add('hidden')};img.src=url}).catch(function(){if(state.previewRevision===revision)overlay.textContent='Preview unavailable'}).finally(function(){if(img.dataset.loadingRevision===revision)delete img.dataset.loadingRevision})}
async function loadWarningSummary(){try{var r=await api('/api/v1/diagnostics/summary');var d=r.data||{};var list=el('warningList');if(!list)return;var items=[['Decode failures',d.decodeFailures],['Unsupported files',d.unsupportedFiles],['Transition fallbacks',d.transitionFallbacks],['Slow transitions',d.slowTransitions],['Weather failures',d.weatherFailures],['Scan failures',d.scanFailures]];var active=items.filter(function(x){return Number(x[1]||0)>0});list.innerHTML=active.length?active.map(function(x){return '<div class="warning-item"><button data-tab-jump="diagnostics">Review</button><strong>'+esc(x[0])+'</strong><div class="helper">'+esc(x[1])+' recent events</div></div>'}).join(''):'<div class="helper">No recent warnings.</div>';}catch(ignore){}}
async function loadFolders(){var list=el('folderList');if(!list)return;try{var r=await api('/api/v1/folders');var rows=r.data||[];var rawSelected=state.settings.selectedFolders||[];if(!Array.isArray(rawSelected))rawSelected=String(rawSelected).split(',').filter(Boolean);var selectedSet=new Set(rawSelected);list.innerHTML=rows.length?rows.map(function(f){var key=f.key||f.name,encoded=encodeURIComponent(key);var isChecked=selectedSet.size===0||f.selected===true||selectedSet.has(key)||selectedSet.has(f.name);return '<div class="folder-row"><input type="checkbox" data-folder="'+attr(encoded)+'"'+checked(isChecked)+'><span class="folder-path" title="'+attr(f.path||f.name)+'"><strong>'+esc(f.path||f.name||'(root)')+'</strong><small>'+esc(f.sourceId||'')+'</small></span><span class="folder-count">'+esc(f.photoCount)+'</span><span class="button-row"><button data-folder-preview="'+attr(encoded)+'">Preview once</button><button data-folder-use="'+attr(encoded)+'">Use in playlist</button></span></div>'}).join(''):'<div class="folder-row"><span></span><span>No folders indexed.</span><span></span></div>';list.querySelectorAll('[data-folder]').forEach(function(n){n.addEventListener('change',saveFolderSelection)});list.querySelectorAll('[data-folder-preview]').forEach(function(n){n.addEventListener('click',function(){folderAction('preview_once',decodeURIComponent(n.dataset.folderPreview))})});list.querySelectorAll('[data-folder-use]').forEach(function(n){n.addEventListener('click',function(){folderAction('use_in_playlist',decodeURIComponent(n.dataset.folderUse))})});filterFolders();}catch(e){list.innerHTML='<div class="folder-row"><span></span><span>'+esc(e.message)+'</span><span></span></div>'}}
