function diagnosticQuery(){var p=new URLSearchParams();p.set('limit','200');[['diagSeverity','severity'],['diagCategory','category'],['diagSession','sessionId'],['diagCode','code'],['diagTrigger','trigger'],['diagOperation','operationId'],['diagOrigin','origin'],['diagSearch','search']].forEach(function(x){var node=el(x[0]),value=node?String(node.value||'').trim():'';if(value)p.set(x[1],value)});return p}
