async function loadDiagnostics(reset){if(!state.session||state.activeTab!=='diagnostics')return;if(!reset&&!state.diagHasMore){toast('No older retained events');return}if(reset){state.diagCursor=null;state.diagEvents=[]}try{var params=diagnosticQuery();if(!reset&&state.diagCursor)params.set('cursor',state.diagCursor);var r=await api('/api/v1/diagnostics/events?'+params.toString());var data=r.data||{};if(data.cursorExpired&&!reset){toast('Older history rotated; reloading retained events',true);return loadDiagnostics(true)}var incoming=data.events||[],combined=reset?incoming:incoming.concat(state.diagEvents),seen=new Set();state.diagEvents=combined.filter(function(e){var key=String(e.sessionId||'')+'~'+String(e.sequence||0);if(seen.has(key))return false;seen.add(key);return true});state.diagCursor=data.nextCursor||null;state.diagHasMore=!!data.hasMore;state.diagHealth=data.health||{};state.diagWarnings=data.warnings||[];state.diagTimeline=data.operationTimeline||[];state.diagFilterOptions=data.filterOptions||state.diagFilterOptions;renderDiagnosticFilters(state.diagFilterOptions);renderDiagnosticEvents();renderDiagnosticMetrics(data.summary||{});renderDiagnosticWarnings();renderOperationTimeline();var more=document.querySelector('[data-action="load-more-events"]');if(more)more.disabled=!state.diagHasMore}catch(e){toast(e.message,true)}}
