function renderOperationTimeline(){var box=el('operationTimeline');if(!box)return;var rows=(state.diagTimeline||[]).slice().reverse();box.innerHTML=rows.length?'<h3>Operation timeline</h3>'+rows.map(function(op){return '<details class="operation-item"><summary><strong>'+esc(op.terminalCode||'INCOMPLETE')+'</strong> <span class="event-meta">'+esc(op.operationId)+' · '+esc(op.trigger||op.origin||'')+' · '+esc(formatAge(op.durationMs||0))+'</span></summary><div class="event-meta">'+esc((op.codes||[]).join(' → '))+(op.incomplete?' · incomplete operation':'')+'</div></details>'}).join(''):''}
