async function download(path,name){try{var r=await rawFetch(path,{cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);var fallback=path==='/api/diagnostics/bundle'?diagnosticFallbackName():name;var blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=responseFileName(r,fallback);document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},1000)}catch(e){toast(e.message,true)}}
