var pendingBackup=null;async function validateBackup(){var file=el('backupFile').files[0];if(!file){toast('Choose a backup file first',true);return}if(file.size>1024*1024){toast('Backup is larger than 1 MiB',true);return}var text=await file.text();try{var r=await api('/api/v1/backup/validate','POST',{backup:text});pendingBackup=text;el('backupPreview').textContent='Valid '+(r.data.appVersion||'')+' backup. Exported '+new Date(r.data.exportedAtEpochMs).toLocaleString()+'.';document.querySelector('[data-action="apply-backup"]').disabled=false}catch(e){pendingBackup=null;el('backupPreview').textContent=e.message;toast(e.message,true)}}
